import{_ as r,o,c as t,a5 as a}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"把所有关键响应头分门别类讲清楚","description":"一、控制“能不能存、能存多久”的响应头 Cache Control: max age N 这是浏览器私有缓存最核心的 freshness 指令。响应年龄超过 N 秒后，就变 stale。对浏览器本地缓存来说，它通常是第一优先级。(MDN Web Docs) Cache Contr。","frontmatter":{"title":"把所有关键响应头分门别类讲清楚","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","前端知识复习"],"description":"一、控制“能不能存、能存多久”的响应头 Cache Control: max age N 这是浏览器私有缓存最核心的 freshness 指令。响应年龄超过 N 秒后，就变 stale。对浏览器本地缓存来说，它通常是第一优先级。(MDN Web Docs) Cache Contr。","sidebarWeight":31,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/考点难点/浏览器的缓存机制/把所有关键响应头分门别类讲清楚.md"},"headers":[],"relativePath":"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/把所有关键响应头分门别类讲清楚.md","filePath":"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/把所有关键响应头分门别类讲清楚.md"}'),n={name:"posts/前端面试与实战/01-前端知识复习/浏览器的缓存机制/把所有关键响应头分门别类讲清楚.md"};function s(l,e,c,g,h,f){return o(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="把所有关键响应头分门别类讲清楚" tabindex="-1">把所有关键响应头分门别类讲清楚 <a class="header-anchor" href="#把所有关键响应头分门别类讲清楚" aria-label="Permalink to &quot;把所有关键响应头分门别类讲清楚&quot;">​</a></h1><blockquote><p>本节目标：理解“把所有关键响应头分门别类讲清楚”的核心思路，并能把它用于实际开发或面试表达。 <strong>一、控制“能不能存、能存多久”的响应头</strong><strong>Cache-Control: max-age=N</strong> 这是浏览器私有缓存最核心的 freshness 指令。响应年龄超过 N 秒后，就变 stale。对浏览器本地缓存来说，它通常是第一优先级。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p></blockquote><p><strong>Cache-Control: no-store</strong> 表示<strong>任何缓存都不应存储</strong>这个响应，浏览器私有缓存和共享缓存都不该留。它是“彻底不存”，不是“先存后校验”。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: no-cache</strong> 这是最容易误解的一个。它<strong>不是“不缓存”</strong>，而是“可以存，但每次复用前都必须去源站验证”。所以你经常会看到有缓存条目，但仍然每次都发条件请求。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: must-revalidate</strong> 它和 no-cache 不一样。must-revalidate 的含义是：<strong>fresh 时可直接用；一旦 stale，必须验证后才能继续复用。</strong> 它通常搭配 max-age 一起用。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: private</strong> 表示只允许<strong>私有缓存</strong>存，比如浏览器本地缓存；共享缓存不该存。个性化页面、登录后的页面最常见。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: public</strong> 它的主要意义是<strong>允许共享缓存</strong>去存；对浏览器本地缓存本身没有什么特殊“加速开关”的作用。尤其带 Authorization 的响应，默认不该被共享缓存存，但加了 public 会改变这一点。这个指令更多是在 CDN / 代理层有意义。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: immutable</strong> 表示只要这个响应还在 fresh 时间内，就认为它内容不会变。浏览器因此可以避免在刷新时对这类资源再发不必要的条件请求。最适合<strong>带内容 hash 的静态资源</strong>。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: stale-while-revalidate</strong> 表示响应在 fresh 窗口过后，还可以在额外的一段时间里先返回 stale 内容，同时在后台做 revalidate。这个机制的重点是“用户先拿旧内容，验证在后台”。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: s-maxage</strong> 这是<strong>共享缓存专用</strong>的 fresh 时间，浏览器私有缓存会忽略它。你看浏览器行为时，别把它当成浏览器本地缓存的 TTL。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: proxy-revalidate</strong> 这也是共享缓存专用，浏览器私有缓存不用它。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Cache-Control: must-understand</strong> 这是一个很少见的高级指令，用来要求缓存必须理解某些状态码对应的缓存语义，否则不要存。它不是日常前端配置主角。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>)</p><p><strong>Expires</strong> 老式的过期时间头。现在仍然有效，但只在<strong>没有 Cache-Control: max-age</strong> 时起作用；只要两者同时出现，max-age 优先。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>)</p><p><strong>Age</strong> 它不是“控制缓存”的开关，而是告诉接收方：“这份响应已经在缓存链路里老了多少秒”。浏览器会把它纳入年龄计算，因此它会影响还剩多少 fresh 时间。Age 的存在也说明响应不是针对这次请求刚由源站生成或验证出来的；但没有 Age，不代表一定联系了源站。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>)</p><p><strong>Date</strong> 它也不是缓存开关，但 freshness 计算离不开它。浏览器会把响应产生时间、Age、接收时间组合起来算年龄和剩余寿命。(<a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">RFC Editor</a>)</p><p><strong>二、控制“如何重验证”的响应头</strong><strong>ETag</strong> ETag 是最重要的内容验证器。浏览器缓存条目过期、或者请求侧要求 revalidate 时，通常会把它带到 If-None-Match 里去问服务端：“我这份还是不是最新的？” 服务端如果认为还是同一个实体，就回 304。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>Last-Modified</strong> 这是时间型验证器。它不如 ETag 精确，但可以作为很好的后备方案。浏览器会在适当时机把它放到 If-Modified-Since。规范和 MDN 都建议：如果可能，ETag 和 Last-Modified 都发。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Last-Modified?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>三、控制“缓存 key 怎么算”的响应头</strong><strong>Vary</strong> Vary 会把请求头并入缓存 key。最常见的场景是：</p><ul><li>Vary: Accept-Encoding</li><li>Vary: Accept-Language</li><li>Vary: Origin</li></ul><p>只要响应内容会因为某个请求头不同而不同，就应该把那个请求头写进 Vary；否则浏览器或中间缓存可能把“给 A 的版本”错复用给“给 B 的请求”。另外，304 响应也应该保持同样的 Vary 值。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Vary?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>No-Vary-Search（实验性）</strong> 这是比较新的、<strong>实验性</strong>的响应头。它允许服务端声明：某些 query 参数不该参与缓存匹配，或者 key 顺序不重要。它不是你现在必须依赖的主流方案，但它确实已经属于“会影响浏览器缓存匹配”的机制。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/No-Vary-Search?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>四、控制“直接清空本地缓存”的响应头</strong><strong>Clear-Site-Data: &quot;cache&quot;</strong> 这个头不是让当前响应“可缓存”，而是告诉浏览器：<strong>把这个站点相关的本地缓存清掉。</strong> MDN 还特别提到，具体浏览器实现里，它可能连预渲染页、bfcache、脚本缓存等一起清。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Clear-Site-Data?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>第四步：所有关键请求头，也按作用讲清楚</strong><strong>一、浏览器自动带上的验证类请求头</strong><strong>If-None-Match</strong> 来源于之前响应里的 ETag。典型触发条件：</p><ul><li>本地缓存条目 stale；</li><li>或请求端明确要求 revalidate，比如 cache: &quot;no-cache&quot;；</li><li>或浏览器刷新时主动要求重验证。</li></ul><p>如果服务端返回 304，浏览器继续使用缓存实体。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>If-Modified-Since</strong> 来源于之前响应里的 Last-Modified。常见于没有 ETag 的场景；若同时有 If-None-Match 和 If-Modified-Since，前者优先。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Last-Modified?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p><p><strong>二、请求侧主动改写缓存行为的请求头</strong><strong>Cache-Control: no-cache</strong> 请求头版本的 no-cache 表示：<strong>即使你本地有 fresh 缓存，也请先去验证一下再复用。</strong> 浏览器强制刷新时通常会加它。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>Cache-Control: max-age=0</strong> 这是浏览器“刷新”时非常常见的历史兼容写法，本质上也是在表达“我要最新的，不要盲目信 fresh 缓存”。很多浏览器普通 reload 仍会带它。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>Cache-Control: no-store</strong> 请求头版本表示：这次请求不要从缓存取，也不要把结果存入缓存。fetch(..., { cache: &quot;no-store&quot; }) 会落到这一类行为。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>Pragma: no-cache</strong> 这是老式、兼容性导向的请求头，效果可理解为 Cache-Control: no-cache。现在更多是历史兼容或某些工具链/浏览器行为里仍能见到。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Pragma?utm_source=chatgpt.com" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>Cache-Control: only-if-cached</strong> 表示“只接受缓存结果，没有缓存就别去网络”。在 Fetch API 里，它只能用于 same-origin。(<a href="https://developer.mozilla.org/en-US/docs/Web/API/Request/cache" target="_blank" rel="noreferrer">MDN Web Docs</a>) <strong>Cache-Control: max-stale / min-fresh / stale-if-error</strong> 这些都是请求端理论上能表达的缓存偏好，但 MDN 明确提到：主流浏览器对 max-stale、min-fresh、请求头版本的 stale-if-error 支持很弱或没有支持，所以实际前端排查时很少把它们当主线。(<a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Web Docs</a>)</p></div>',1)])])}const i=r(n,[["render",s]]);export{p as __pageData,i as default};
